package com.atelier.tasks.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import jakarta.annotation.PostConstruct;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;
@Component public class JwtService {@Value("${app.jwt.secret}") String secret;@Value("${app.jwt.expiration-ms}") long expiration;@PostConstruct void validate(){key();if(expiration<=0)throw new IllegalStateException("JWT expiration must be positive");}SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String create(String email){long now=System.currentTimeMillis();return Jwts.builder().subject(email).issuedAt(new Date(now)).expiration(new Date(now+expiration)).signWith(key()).compact();}public String subject(String token){return Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload().getSubject();}}
